window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"phy","n":"Physics","tab":"Physics","w":"Motion, heat and sound, light, electricity and magnetism.","topics":[{"id":"mechanics","n":"Motion, Force, Units and Measurement","qs":[{"id":"q1579","q":"Which instrument can be used to measure internal and the external dimensions of an object?","o":["Viscometer","Vernier Caliper","Wattmeter","Venturimeter"],"a":1,"x":"A Vernier caliper measures internal and external dimensions (and depth) accurately, to about 0.1 mm.","e":"A screw gauge (micrometer) is more precise, to about 0.01 mm.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0491","q":"A type of motion in which all parts of an object move in the same direction in a given time is called _________ motion.","o":["translation","rotational","periodic","oscillation"],"a":0,"x":"In translatory motion every part of a body moves the same distance in the same direction in the same time.","e":"A car on a straight road. A spinning fan is rotational motion.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0531","q":"Which among the following is an example of double class 1 lever?","o":["Scissors","Wheelbarrow","Broom","Nut cracker"],"a":0,"x":"Scissors are a double class-1 lever: two levers joined at a pivot (fulcrum) that sits between the effort (handles) and the load (blades).","e":"Wheelbarrow and nutcracker: class 2. Broom and tongs: class 3.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0572","q":"The attractional force applied by the earth on an object in the downward direction is called _____________.","o":["Muscular Force","Air Resistance","Frictional Force","Gravitational Force"],"a":3,"x":"The force with which Earth pulls an object downward is gravitational force; for an object, this pull is its weight (W = mg).","e":"g is about 9.8 m/s² at Earth's surface.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0730","q":"The concepts of work and energy share which one of the following units of measurement?","o":["Watt","Ohm","Joule","Ampere"],"a":2,"x":"Work and energy share the SI unit joule (J): 1 J = 1 newton × 1 metre.","e":"Power is measured in watts: 1 W = 1 J per second.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1337","q":"What is the SI unit of energy?","o":["Newton","Joule","Mole","Ampere"],"a":1,"x":"The SI unit of energy is the joule (J), the same as for work.","e":"1 kilowatt-hour (the electricity 'unit') = 3.6 × 10⁶ J.","src":["Stenographer 23 Apr 2021 S2"]}]},{"id":"heat","n":"Heat, Sound and Thermodynamics","qs":[{"id":"q1004","q":"What is the key component inside a decibel meter that helps detect sound pressure?","o":["Magnetic coil","Microphone","LED sensor","Optical fiber"],"a":1,"x":"A decibel (sound level) meter uses a microphone to pick up sound pressure changes and turn them into an electrical signal.","e":"The decibel scale is logarithmic: +10 dB means 10 times the sound intensity.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1452","q":"What is the SI unit of thermodynamic temperature as per the International System of Units?","o":["Kelvin","Thermos","Fahrenheit","Celsius"],"a":0,"x":"The kelvin (K) is the SI unit of thermodynamic temperature; 0 K is absolute zero (−273.15°C).","e":"K = °C + 273.15.","src":["TGT 25 Jun 2023 S3"]},{"id":"q0822","q":"Which of the following law states that ‘two systems in thermal equilibrium with a third system separately are in thermal equilibrium with each other'?","o":["The first law of thermodynamics","Fourier's law","Joule's First law","The zeroth law of thermodynamics"],"a":3,"x":"The zeroth law of thermodynamics: if two systems are each in thermal equilibrium with a third, they are in equilibrium with each other. This is what makes a thermometer work.","e":"First law: energy conservation (ΔU = Q − W).","src":["PGT 26 Sep 2025"]}]},{"id":"light","n":"Light and Optics","qs":[{"id":"q1620","q":"Which of the following is NOT an example of refraction of light?","o":["Moonlight","bent pencil in glass of water","Rainbow","appearing of raised coin in a trough filled with water"],"a":0,"x":"Moonlight is sunlight reflected off the Moon, so it is reflection, not refraction. A bent pencil in water, a rainbow and a coin appearing raised are all refraction.","e":"A rainbow uses refraction, dispersion and internal reflection.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0493","q":"Which among the following defects is also known as far-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":2,"x":"Hypermetropia (far-sightedness): far objects are clear but near ones blur. It is corrected with a convex lens.","e":"Myopia (near-sightedness) uses a concave lens; presbyopia is age-related loss of near focus.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0614","q":"Which among the following defects is also known as near-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":0,"x":"Myopia (near-sightedness): near objects are clear, distant ones blur because the image forms before the retina. A concave lens corrects it.","e":"Hypermetropia (far-sightedness) is corrected by a convex lens.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q1365","q":"Malus' Law is related to which of the following subjects?","o":["Inertia","Surface tension","Gravitation","Light"],"a":3,"x":"Malus' law is about polarised light: the intensity passing through an analyser is I = I₀ cos²θ, where θ is the angle between the polariser and analyser.","e":"Polarised sunglasses cut glare using this principle.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1399","q":"How many internal reflections do light rays undergo, inside a raindrop, to form a secondary rainbow?","o":["One","Four","Three","Two"],"a":3,"x":"A secondary rainbow forms after two internal reflections inside raindrops (a primary rainbow after one), so its colours are reversed and fainter.","e":"The primary rainbow has red on the outside; the secondary has red on the inside.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1554","q":"Transverse nature of light causes:","o":["convergent nature of light","reflection of light","polarisation of light","divergent nature of light"],"a":2,"x":"Only transverse waves can be polarised, so polarisation proves that light is a transverse wave.","e":"Sound in air is longitudinal and cannot be polarised.","src":["TGT 31 Aug 2025 S1"]}]},{"id":"electricity","n":"Electricity and Magnetism","qs":[{"id":"q0224","q":"When the discharge takes place between opposite charges accumulated in different clouds, the type of lightning produced is:","o":["cloud to air lightning","cloud to ground lightning","cloud to cloud lightning","intra cloud lightning"],"a":2,"x":"When charges jump between oppositely charged regions of two different clouds, the result is cloud-to-cloud (inter-cloud) lightning.","e":"Inside a single cloud it is intra-cloud lightning; the most dangerous kind is cloud-to-ground.","src":["ASO 20 Aug 2025 S1"]},{"id":"q1605","q":"Which of the following is NOT a basic feature of magnets?","o":["Directive property","Magnet exists as a monopole","Attractive property","Like poles repel and unlike poles attract"],"a":1,"x":"A magnet always has two poles (north and south); a magnetic monopole has never been found. Cut a magnet in half and each piece has both poles.","e":"Magnets attract iron, point north–south when free, and like poles repel.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0533","q":"Which among the following laws states that the current passing through a conductor between two points is directly proportional to the potential difference across the two points provided the physical state and temperature etc. of the conductor does not change?","o":["Ohm's Law","Avogadro's Law","Coulomb’s Law","Pascal’s Law"],"a":0,"x":"Ohm's law: at constant temperature, the current through a conductor is directly proportional to the potential difference across it (V = IR).","e":"A 12 V battery across a 4 Ω resistor drives 3 A.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0574","q":"Which among the following laws states that induced electromotive force with different polarities induces a current whose magnetic field opposes the change in magnetic flux through the loop in order to ensure that original flux is maintained through the loop when current flows in it?","o":["Lenz's Law","Ohm's Law","Snell's Law","Boyle's Law"],"a":0,"x":"Lenz's law: the induced current flows in a direction whose magnetic field opposes the change in flux that produced it. This follows from conservation of energy.","e":"It explains the minus sign in Faraday's law.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0651","q":"An electric generator is a device that converts _______________ energy into electrical energy.","o":["sound","chemical","nuclear","mechanical"],"a":3,"x":"An electric generator (dynamo) converts mechanical energy into electrical energy through electromagnetic induction.","e":"An electric motor does the reverse.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0912","q":"Electric and magnetic fields are regarded as:","o":["Scalar quantities because they have only magnitude","Non-physical entities without measurable effects","Independent phenomena with no relation","Vector quantities because they have both magnitude and direction"],"a":3,"x":"Electric and magnetic fields are vector quantities: they have both magnitude and direction at every point.","e":"Other vectors: force, velocity. Scalars: mass, temperature, energy.","src":["PRT 17 Feb 2026 S3"]}]}]});
